// #Sireum

package factory_dispatch_coordinator.Factory_Dispatch_Coordinator

import org.sireum._
import art.Art
import factory_dispatch_coordinator._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait ActionArbitration_coordinator_process_action_arbitration_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.FactoryDispatchCoordinatorSystem_Instance_coordinator_process_action_arbitration)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.FactoryDispatchCoordinatorSystem_Instance_coordinator_process_action_arbitration)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.FactoryDispatchCoordinatorSystem_Instance_coordinator_process_action_arbitration)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.FactoryDispatchCoordinatorSystem_Instance_coordinator_process_action_arbitration)
  }

  /** helper function to set the values of all input ports.
   * @param emergency_state payload for data port emergency_state
   * @param quotation_proposal payload for data port quotation_proposal
   * @param procurement_proposal payload for data port procurement_proposal
   * @param production_proposal payload for data port production_proposal
   * @param dispatch_proposal payload for data port dispatch_proposal
   */
  def put_concrete_inputs(emergency_state : Factory_Dispatch_Coordinator.EmergencyState.Type,
                          quotation_proposal : Factory_Dispatch_Coordinator.ProposalState.Type,
                          procurement_proposal : Factory_Dispatch_Coordinator.ProposalState.Type,
                          production_proposal : Factory_Dispatch_Coordinator.ProposalState.Type,
                          dispatch_proposal : Factory_Dispatch_Coordinator.ProposalState.Type): Unit = {
    put_emergency_state(emergency_state)
    put_quotation_proposal(quotation_proposal)
    put_procurement_proposal(procurement_proposal)
    put_production_proposal(production_proposal)
    put_dispatch_proposal(dispatch_proposal)
  }


  /** helper function to check ActionArbitration_coordinator_process_action_arbitration's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param selected_action method that will be called with the value of the outgoing data
   *        port 'selected_action'.
   */
  def check_concrete_output(selected_action: Factory_Dispatch_Coordinator.DispatchAction.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val selected_actionValue: Factory_Dispatch_Coordinator.DispatchAction.Type = get_selected_action().get
    if(!selected_action(selected_actionValue)) {
      testFailures = testFailures :+ st"'selected_action' did not match expected: value of the outgoing data port is ${selected_actionValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_emergency_state(value : Factory_Dispatch_Coordinator.EmergencyState.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryDispatchCoordinatorSystem_Instance_coordinator_process_action_arbitration.operational_api.emergency_state_Id, Factory_Dispatch_Coordinator.EmergencyState_Payload(value))
  }

  // setter for in DataPort
  def put_quotation_proposal(value : Factory_Dispatch_Coordinator.ProposalState.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryDispatchCoordinatorSystem_Instance_coordinator_process_action_arbitration.operational_api.quotation_proposal_Id, Factory_Dispatch_Coordinator.ProposalState_Payload(value))
  }

  // setter for in DataPort
  def put_procurement_proposal(value : Factory_Dispatch_Coordinator.ProposalState.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryDispatchCoordinatorSystem_Instance_coordinator_process_action_arbitration.operational_api.procurement_proposal_Id, Factory_Dispatch_Coordinator.ProposalState_Payload(value))
  }

  // setter for in DataPort
  def put_production_proposal(value : Factory_Dispatch_Coordinator.ProposalState.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryDispatchCoordinatorSystem_Instance_coordinator_process_action_arbitration.operational_api.production_proposal_Id, Factory_Dispatch_Coordinator.ProposalState_Payload(value))
  }

  // setter for in DataPort
  def put_dispatch_proposal(value : Factory_Dispatch_Coordinator.ProposalState.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryDispatchCoordinatorSystem_Instance_coordinator_process_action_arbitration.operational_api.dispatch_proposal_Id, Factory_Dispatch_Coordinator.ProposalState_Payload(value))
  }

  // getter for out DataPort
  def get_selected_action(): Option[Factory_Dispatch_Coordinator.DispatchAction.Type] = {
    val value: Option[Factory_Dispatch_Coordinator.DispatchAction.Type] = get_selected_action_payload() match {
      case Some(Factory_Dispatch_Coordinator.DispatchAction_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port selected_action.  Expecting 'Factory_Dispatch_Coordinator.DispatchAction_Payload' but received ${v}")
      case _ => None[Factory_Dispatch_Coordinator.DispatchAction.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_selected_action_payload(): Option[Factory_Dispatch_Coordinator.DispatchAction_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.FactoryDispatchCoordinatorSystem_Instance_coordinator_process_action_arbitration.initialization_api.selected_action_Id).asInstanceOf[Option[Factory_Dispatch_Coordinator.DispatchAction_Payload]]
  }

}
